package com.campus.trade.dispute.entity;
import java.time.LocalDateTime;
/** 订单纠纷实体；evidenceJson 对应 JSON 列，由 Service 转成安全的图片 URL 列表。 */
public class Dispute { private Long id,orderId,applicantId,respondentId,handlerId; private Integer reasonType,status; private String statement,evidenceJson,handleNote; private LocalDateTime handledAt,createdAt,updatedAt;
 public Long getId(){return id;} public void setId(Long v){id=v;} public Long getOrderId(){return orderId;} public void setOrderId(Long v){orderId=v;} public Long getApplicantId(){return applicantId;} public void setApplicantId(Long v){applicantId=v;} public Long getRespondentId(){return respondentId;} public void setRespondentId(Long v){respondentId=v;} public Long getHandlerId(){return handlerId;} public void setHandlerId(Long v){handlerId=v;} public Integer getReasonType(){return reasonType;} public void setReasonType(Integer v){reasonType=v;} public Integer getStatus(){return status;} public void setStatus(Integer v){status=v;} public String getStatement(){return statement;} public void setStatement(String v){statement=v;} public String getEvidenceJson(){return evidenceJson;} public void setEvidenceJson(String v){evidenceJson=v;} public String getHandleNote(){return handleNote;} public void setHandleNote(String v){handleNote=v;} public LocalDateTime getHandledAt(){return handledAt;} public void setHandledAt(LocalDateTime v){handledAt=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;}}
